const body = $input.first().json.body || $input.first().json || {};
const rawMessage = body.message || body.text || body.content || '';
const sessionId = body.sessionId || body.from || 'default';

function normalize(str) {
  return str.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/[!?.]/g, '').replace(/\s+/g, ' ').trim();
}
const normalizedMessage = normalize(rawMessage);

// Tính điểm keyword: boost từ mạnh, penalize từ mơ hồ
const BOOST_KEYWORDS = [
  // Sales
  { kw: 'doanh thu', score: 0.3 }, { kw: 'doanh số', score: 0.3 }, { kw: 'hóa đơn', score: 0.25 },
  { kw: 'đơn hàng', score: 0.25 }, { kw: 'lên đơn', score: 0.3 },
  // Customer
  { kw: 'công nợ', score: 0.3 }, { kw: 'tich luy', score: 0.3 }, { kw: 'tích lũy', score: 0.3 },
  { kw: 'cham diem', score: 0.25 }, { kw: 'chấm điểm', score: 0.25 }, { kw: 'vip', score: 0.2 },
  // Product
  { kw: 'ton kho', score: 0.3 }, { kw: 'tồn kho', score: 0.3 }, { kw: 'thuoc', score: 0.2 },
  { kw: 'goi y', score: 0.25 }, { kw: 'gợi ý', score: 0.25 }, { kw: 'ban them', score: 0.2 },
];

const AMBIGUOUS_PENALTY = [
  { kw: 'cái này', score: -0.2 }, { kw: 'nó', score: -0.15 },
  { kw: 'khách này', score: -0.1 }, { kw: 'đó', score: -0.1 },
  { kw: 'xem giúp', score: -0.25 }, { kw: 'cho biết', score: -0.05 },
];

// FIX: Bắt đầu từ 0 (không bias), normalize về [0,1]
let rawBoost = 0;
for (const { kw, score } of BOOST_KEYWORDS) {
  if (normalizedMessage.includes(normalize(kw))) rawBoost += score;
}
let rawPenalty = 0;
for (const { kw, score } of AMBIGUOUS_PENALTY) {
  if (normalizedMessage.includes(normalize(kw))) rawPenalty += Math.abs(score);
}
// FIX: Nếu có keyword mạnh (như 'doanh thu'), bỏ qua hình phạt của các từ lịch sự ('xem giúp')
if (rawBoost >= 0.2) {
  rawPenalty = Math.max(0, rawPenalty - 0.3);
}
// Length penalty
const lengthPenalty = normalizedMessage.length > 80 ? 0.1 : 0;

// Multi-intent detection: câu hỏi kép → penalize thêm
const MULTI_INTENT_PAIRS = [
  ['doanh', 'no'], ['doanh', 'ton kho'], ['no', 'ton kho'],
  ['don hang', 'no'], ['goi y', 'ton kho'],
];
let multiIntentPenalty = 0;
for (const [a, b] of MULTI_INTENT_PAIRS) {
  if (normalizedMessage.includes(a) && normalizedMessage.includes(b)) {
    multiIntentPenalty = 0.3;
    break;
  }
}

// Max possible boost = sum of all BOOST_KEYWORDS scores (~2.3)
// Normalize: chia cho 1.5 để scale về [0,1] hợp lý
const MAX_BOOST = 0.5;
const normalizedBoost = Math.min(1, rawBoost / MAX_BOOST);

// FIX: keywordScore = normalized boost - penalties, clamp [0,1]
let keywordScore = normalizedBoost - (rawPenalty / MAX_BOOST) - lengthPenalty - (multiIntentPenalty * 0.5);
keywordScore = Math.max(0, Math.min(1, keywordScore));

const QUICK_INTENTS = [
  { patterns: ['doanh thu thang nay', 'doanh so thang nay', 'dt thang nay'],
    intent: '@doanh_so', params: { '@TuNgay': '[THIS_MONTH_START]', '@DenNgay': '[TODAY]' } },
  { patterns: ['tong no', 'tong cong no', 'cong no tong hop'],
    intent: '@cong_no_khach_hang', params: { '@DenNgay': '[TODAY]' } },
  { patterns: ['hang trong tam', 'san pham trong tam'],
    intent: '@san_pham_trong_tam', params: {} },
  { patterns: ['hang sap date', 'xa hang', 'xa gap'],
    intent: '@de_xuat_khuyen_mai', params: {} },
  { patterns: ['hom nay ghe dau', 'tuyen hom nay', 'lich tuyen'],
    intent: '@tuyen_ban_hang', params: {} },
];

let quickIntent = null;

const CASUAL_GREETINGS = /^(hi|hello|chao|alo|e|oi|helo|chao buoi sang|good morning)(?:\s+(em|bot|tro ly|cung|sep|anh|chi|ban|nhe|nha|a))?$/;
if (CASUAL_GREETINGS.test(normalizedMessage)) {
  quickIntent = {
    intent: 'casual_chat', params: {},
    casual_reply: 'Dạ em chào Sếp! Sếp cần em tra cứu thông tin khách hàng hay doanh số gì hôm nay không ạ?',
    status: 'SUCCESS', missing_fields: [],
    confidence: 1.0, reason: 'regex casual match', matchedBy: 'KEYWORD'
  };
}

for (const qi of QUICK_INTENTS) {
  if (quickIntent) break;
  if (qi.patterns.some(p => normalizedMessage.includes(p))) {
    quickIntent = {
      intent: qi.intent, params: qi.params,
      status: 'SUCCESS', missing_fields: [],
      confidence: 1.0, reason: 'exact quick match', matchedBy: 'KEYWORD'
    };
    break;
  }
}

const staticData = $getWorkflowStaticData('global');
const cacheKey = 'intent_cache_' + normalizedMessage.substring(0, 80);
let cachedIntent = null;
let cacheHit = false;
try {
  const raw = staticData[cacheKey];
  if (raw) {
    const parsed = JSON.parse(raw);
    const hasSpecificCode = normalizedMessage.match(/\b[A-Z]{2,}\d{3,}\b/);
    if (!hasSpecificCode && parsed.cachedAt && (Date.now() - parsed.cachedAt) < 3600000) {
      cachedIntent = { ...parsed.data, confidence: 0.95, reason: 'cache hit', matchedBy: 'CACHE' };
      cacheHit = true;
    }
  }
} catch(e) {}

let ctx = {};
try {
  const raw = staticData['ctx_' + sessionId];
  if (raw) {
    ctx = JSON.parse(raw);
    if (ctx.updatedAt && (Date.now() - ctx.updatedAt) > 1800000) ctx = {};
  }
} catch(e) {}
const historyContext = [
  ctx.lastMaKhachHang ? `Last Customer: ${ctx.lastMaKhachHang}` : '',
  ctx.lastIntent      ? `Last Intent: ${ctx.lastIntent}` : ''
].filter(Boolean).join(' | ');

const skipLLM = cacheHit || !!quickIntent;

return [{
  json: {
    rawMessage, normalizedMessage, sessionId, historyContext, ctx,
    keywordScore,      // Signal 1: normalized keyword scoring (0–1, no base bias)
    multiIntentPenalty,// Ambiguity signal: >0 nếu câu hỏi kép
    quickIntent,       // Signal 2: exact match (confidence=1.0)
    cachedIntent,      // Signal 3: cache hit (confidence=0.95)
    cacheHit, skipLLM,
    originalBody: body
  },
  binary: $input.first().binary
}];

const n = $input.first().json;
const intent = n.quickIntent || n.cachedIntent || null;
if (!intent) {
  return [{ json: { intent: null, confidence: 0, reason: 'no quick match', status: 'ASK_CLARIFICATION', missing_fields: ['intent'], params: {}, items: [], action: null } }];
}
return [{ json: intent }];

// V5 Fixes:
//   1. Cache chỉ được ghi khi confidence >= 0.85 (tránh cache poisoning)
//   2. Stability boost reset khi intent thay đổi
//   3. decision_reason field để debug nhanh
//   4. Track ASK rate + disagreement rate trong shadow log

const CACHE_VERSION  = 'v5';   // Tăng version khi thay đổi logic → tự invalidate cache cũ
const CACHE_TTL_MS   = 6 * 3600 * 1000; // 6 giờ
const CACHE_MIN_CONF = 0.75;   // Chỉ cache khi đủ tự tin

const llmResult  = $input.first().json;
const normOut    = $('LIB NormalizeInput').first().json;
const sessionId  = normOut.sessionId || 'default';
const staticData = $getWorkflowStaticData('global');

const llmConfidence = Math.max(0, Math.min(1, parseFloat(llmResult.confidence) || 0));
const keywordScore  = Math.max(0, Math.min(1, normOut.keywordScore || 0));
const matchedBy     = llmResult.matchedBy || (normOut.cacheHit ? 'CACHE' : (normOut.quickIntent ? 'KEYWORD' : 'LLM'));
const cacheScore    = normOut.cacheHit ? 1.0 : 0;

let hybridScore;
if (matchedBy === 'KEYWORD') {
  hybridScore = 1.0;
} else if (matchedBy === 'CACHE') {
  hybridScore = 0.95;
} else {
  hybridScore = (llmConfidence * 0.85) + (keywordScore * 0.15);
}
hybridScore = Math.max(0, Math.min(1, hybridScore));

const missingCount = (llmResult.missing_fields || []).length;
hybridScore -= missingCount * 0.05;

const multiIntentPenalty = normOut.multiIntentPenalty || 0;
hybridScore -= multiIntentPenalty;
hybridScore = Math.max(0, Math.min(1, hybridScore));

// FIX: Reset counter khi intent thay đổi
let stabilityBoost = 0;
let decisionReasons = [];

try {
  const histKey = 'intent_history_' + sessionId;
  const history = JSON.parse(staticData[histKey] || '{"intent": null, "count": 0, "ts": 0}');

  if (llmResult.intent && llmResult.intent === history.intent) {
    // Cùng intent → tăng counter, boost nếu đủ 3 lần
    history.count = (history.count || 0) + 1;
    if (history.count >= 3) {
      stabilityBoost = 0.10;
      decisionReasons.push('stability_boost +0.10 (same intent x3)');
    }
  } else {
    // Intent THAY ĐỔI → reset hoàn toàn (không carry boost cũ)
    history.count = 1;
    if (history.intent && history.intent !== llmResult.intent) {
      decisionReasons.push(`intent_changed: ${history.intent} → ${llmResult.intent}`);
    }
  }
  history.intent = llmResult.intent;
  history.ts = Date.now();
  staticData[histKey] = JSON.stringify(history);
} catch(e) {}

hybridScore = Math.min(1, hybridScore + stabilityBoost);

// Hard cap cho intent = null / casual
if (!llmResult.intent || llmResult.intent === 'casual_chat' || llmResult.intent === 'null') {
  hybridScore = 1.0;
  decisionReasons.push('allow_casual_chat: forcing to RAG');
}

let decision;
if (hybridScore >= 0.75) {
  decision = 'RUN';
  decisionReasons.push(`score ${hybridScore.toFixed(2)} >= 0.85`);
} else if (hybridScore >= 0.55) {
  decision = 'WARN_AND_RUN';
  decisionReasons.push(`score ${hybridScore.toFixed(2)} in [0.70, 0.85)`);
} else if (hybridScore >= 0.40) {
  decision = 'ASK_CONFIRM';
  decisionReasons.push(`score ${hybridScore.toFixed(2)} in [0.60, 0.70) — gentle confirm`);
} else {
  decision = 'ASK_CLARIFICATION';
  decisionReasons.push(`score ${hybridScore.toFixed(2)} < 0.60 — too uncertain`);
}

if (missingCount > 0 && decision === 'RUN' && llmResult.intent !== 'casual_chat' && llmResult.intent !== 'null' && llmResult.intent) {
  decision = 'ASK_CLARIFICATION';
  decisionReasons.push(`override: ${missingCount} missing required params`);
}

const decisionReason = decisionReasons.join(' | ');

const FRIENDLY = {
  '@MaKhachHang': 'Mã Khách Hàng', '@timkiem': 'Từ khóa',
  '@TuNgay': 'Từ ngày', '@DenNgay': 'Đến ngày'
};
let askMsg = '';
if (llmResult.casual_reply) {
  decision = 'ASK_CLARIFICATION';
  askMsg = llmResult.casual_reply;
  decisionReasons.push('fast_casual: skip RAG');
} else if (decision === 'ASK_CLARIFICATION') {
  if (missingCount > 0) {
    const names = llmResult.missing_fields.map(f => FRIENDLY[f] || f).join(', ');
    askMsg = `Dạ, để tra cứu em cần thêm: ${names} ạ!`;
  } else if (multiIntentPenalty > 0) {
    askMsg = 'Dạ, câu hỏi có vẻ đang hỏi nhiều thứ cùng lúc — anh/chị muốn xem phần nào trước ạ?';
  } else {
    askMsg = 'Dạ, anh/chị có thể nói rõ hơn cần tra cứu thông tin gì không ạ?';
  }
} else if (decision === 'ASK_CONFIRM') {
  const INTENT_FRIENDLY = {
    '@doanh_so': 'doanh số', '@cong_no_chi_tiet': 'công nợ',
    '@don_hang': 'đơn hàng', '@cham_diem_kh': 'phân loại khách',
    '@danh_sach_tonkho': 'tồn kho', '@tuyen_ban_hang': 'tuyến ghé thăm',
  };
  const guessed = INTENT_FRIENDLY[llmResult.intent] || llmResult.intent;
  askMsg = `Dạ, anh/chị đang hỏi về "${guessed}" đúng không ạ?`;
}

// FIX: Không cache khi confidence thấp → tránh cache poisoning
if (decision === 'RUN' && hybridScore >= CACHE_MIN_CONF && llmResult.intent) {
  try {
    const cacheKey = 'intent_cache_' + normOut.normalizedMessage.substring(0, 80);
    staticData[cacheKey] = JSON.stringify({
      data: {
        intent: llmResult.intent,
        params: llmResult.params || {},
        status: 'SUCCESS',
        missing_fields: []
      },
      version:  CACHE_VERSION,  // FIX: versioned cache → tự invalidate khi nâng cấp
      cachedAt: Date.now(),
      ttl:      CACHE_TTL_MS
    });
  } catch(e) {}
}

// Track system-wide ASK rate
try {
  const askRateKey = 'ask_rate_stats';
  const stats = JSON.parse(staticData[askRateKey] || '{"total":0,"ask":0,"warn":0,"run":0}');
  stats.total++;
  if (['ASK_CLARIFICATION','ASK_CONFIRM'].includes(decision)) stats.ask++;
  else if (decision === 'WARN_AND_RUN') stats.warn++;
  else stats.run++;
  // Tỉ lệ ASK — nếu > 30% → system quá bảo thủ
  stats.ask_rate = parseFloat((stats.ask / stats.total * 100).toFixed(1));
  staticData[askRateKey] = JSON.stringify(stats);
} catch(e) {}

// 3. LƯU CONTEXT NGAY LẬP TỨC (Tránh mất data nếu API lỗi)
try {
  const newCtx = JSON.stringify({
    lastMaKhachHang: llmResult.params?.['@MaKhachHang'] || normOut.ctx?.lastMaKhachHang || '',
    lastMaSanPham:   llmResult.params?.['@timkiem'] || normOut.ctx?.lastMaSanPham || '',
    lastIntent:      llmResult.intent || '',
    updatedAt:       Date.now()
  });
  staticData['ctx_' + sessionId] = newCtx;
} catch(e) {}

const shadowLog = {
  ts:               new Date().toISOString(),
  input:            normOut.normalizedMessage,
  intent:           llmResult.intent,
  llm_confidence:   llmConfidence,
  keyword_score:    keywordScore,
  cache_score:      cacheScore,
  hybrid_score:     parseFloat(hybridScore.toFixed(3)),
  ambiguity:        multiIntentPenalty,
  stability_boost:  stabilityBoost,
  missing_decay:    missingCount * 0.05,
  matched_by:       matchedBy,
  reason:           llmResult.reason || '',
  decision,
  decision_reason:  decisionReason,  // V5 NEW: debug nhanh
  cache_written:    decision === 'RUN' && hybridScore >= CACHE_MIN_CONF,
};

try {
  const logKey = 'shadow_log';
  const logs = JSON.parse(staticData[logKey] || '[]');
  logs.unshift(shadowLog);
  staticData[logKey] = JSON.stringify(logs.slice(0, 200));
} catch(e) {}

return [{
  json: {
    intent:          llmResult.intent,
    params:          llmResult.params || {},
    items:           llmResult.items  || [],
    action:          llmResult.action || null,
    status:          ['ASK_CLARIFICATION','ASK_CONFIRM'].includes(decision) ? 'ASK_CLARIFICATION' : 'SUCCESS',
    missing_fields:  llmResult.missing_fields || [],
    finalConfidence: parseFloat(hybridScore.toFixed(3)),
    llmConfidence, keywordScore, cacheScore,
    ambiguityPenalty: multiIntentPenalty,
    stabilityBoost, matchedBy,
    reason:          llmResult.reason || '',
    decision,
    decisionReason,   // V5 NEW
    askMsg,
    isValid:         !['ASK_CLARIFICATION','ASK_CONFIRM'].includes(decision),
    shadowLog,
  }
}];

const apiCode = $json.apiCode || '';
const rawParams = $json.params || {};

const SCHEMA = {
  '@goi_y_don_hang':     { required: ['@MaKhachHang'], types: { '@MaKhachHang': 'string', '@TopN': 'number' } },
  '@upsell_goi_y':       { required: ['@timkiem'],     types: { '@timkiem': 'string' } },
  '@goi_y_don_thuoc':    { required: ['@timkiem'],     types: { '@timkiem': 'string' } },
  '@tuyen_ban_hang':     { required: [],               types: { '@SoNgayVangMat': 'number' } },
  '@cham_diem_kh':       { required: [],               types: { '@MaKhachHang': 'string' } },
  '@tich_luy':           { required: ['@MaKhachHang'], types: { '@MaKhachHang': 'string' } },
  '@de_xuat_khuyen_mai': { required: [],               types: {} },
  '@danh_sach_tonkho':   { required: ['@timkiem'],     types: { '@timkiem': 'string' } },
  '@tra_cuu_san_pham':   { required: ['@timkiem'],     types: { '@timkiem': 'string' } },
  '@san_pham_trong_tam': { required: [],               types: {} },
  '@doanh_so':           { required: [],               types: { '@TuNgay': 'string', '@DenNgay': 'string', '@LoaiBaoCao': 'string' } },
  '@hoa_don':            { required: [],               types: { '@TuNgay': 'string', '@DenNgay': 'string' } },
  '@cong_no_khach_hang': { required: [],               types: { '@MaKhachHang': 'string' } },
  '@cong_no_chi_tiet':   { required: ['@MaKhachHang'], types: { '@MaKhachHang': 'string' } },
  '@don_hang':           { required: ['@MaKhachHang'], types: { '@MaKhachHang': 'string' } },
  '@lap_don_hang':       { required: [],               types: { '@MaKhachHang': 'string' } },
};

if (!SCHEMA[apiCode]) {
  return [{ json: { isValid: true, cleanParams: rawParams, errorMsg: null, validationLevel: 'SKIP' } }];
}

const schema = SCHEMA[apiCode];
const FRIENDLY = {
  '@MaKhachHang': 'Mã Khách Hàng', '@timkiem': 'Từ khóa tìm kiếm',
  '@TuNgay': 'Từ ngày', '@DenNgay': 'Đến ngày'
};

const missing = schema.required.filter(k => {
  const v = rawParams[k];
  return v === undefined || v === null || v === '' || v === 'null';
});
if (missing.length > 0) {
  const names = missing.map(k => FRIENDLY[k] || k).join(', ');
  return [{ json: { isValid: false, cleanParams: {}, errorMsg: `Dạ, để tra cứu em cần thêm: ${names} ạ!`, validationLevel: 'REQUIRED' } }];
}

const cleanParams = {};
for (const [key, val] of Object.entries(rawParams)) {
  if (val === null || val === undefined || val === '' || val === 'null') continue;
  const expectedType = schema.types[key];
  let cleanVal = val;
  if (expectedType === 'number') {
    cleanVal = Number(val);
    if (isNaN(cleanVal)) continue;
  } else if (expectedType === 'string') {
    cleanVal = String(val).trim().replace(/[';]|--/g, ''); // SQL injection guard
    if (cleanVal === '') continue;
  }
  if (key === '@MaKhachHang') cleanVal = String(cleanVal).replace(/\s+/g,'').toUpperCase();
  cleanParams[key] = cleanVal;
}
if (!cleanParams['@Username'] && rawParams['@Username']) {
  cleanParams['@Username'] = rawParams['@Username'];
}

const tzOffset = (new Date()).getTimezoneOffset() * 60000; const todayStr = new Date(Date.now() - tzOffset).toISOString().split('T')[0]; if (apiCode === '@cong_no_khach_hang' || apiCode === '@cong_no_chi_tiet') { if (!cleanParams['@DenNgay']) cleanParams['@DenNgay'] = todayStr; } if (apiCode === '@doanh_so' || apiCode === '@hoa_don') { if (!cleanParams['@DenNgay']) cleanParams['@DenNgay'] = todayStr; if (!cleanParams['@TuNgay']) { const d = new Date(); const firstDay = new Date(d.getFullYear(), d.getMonth(), 1); cleanParams['@TuNgay'] = new Date(firstDay.getTime() - tzOffset).toISOString().split('T')[0]; } } const errors = [];

// Rule 1: TuNgay phải <= DenNgay
if (cleanParams['@TuNgay'] && cleanParams['@DenNgay']) {
  const tu = new Date(cleanParams['@TuNgay']);
  const den = new Date(cleanParams['@DenNgay']);
  if (tu > den) {
    errors.push(`Từ ngày (${cleanParams['@TuNgay']}) phải nhỏ hơn hoặc bằng Đến ngày (${cleanParams['@DenNgay']})`);
  }
}

// Rule 2: Khoảng ngày không quá 2 năm (tránh query nặng)
if (cleanParams['@TuNgay'] && cleanParams['@DenNgay']) {
  const diffDays = (new Date(cleanParams['@DenNgay']) - new Date(cleanParams['@TuNgay'])) / 86400000;
  if (diffDays > 730) {
    errors.push('Khoảng thời gian tra cứu không nên vượt quá 2 năm, anh/chị có thể thu hẹp lại không ạ?');
  }
}

// Rule 3: TopN hợp lý (1–100)
if (cleanParams['@TopN'] !== undefined) {
  if (cleanParams['@TopN'] < 1 || cleanParams['@TopN'] > 100) {
    cleanParams['@TopN'] = Math.min(Math.max(cleanParams['@TopN'], 1), 100); // Auto-clamp thay vì báo lỗi
  }
}

// Rule 4: timkiem tối thiểu 2 ký tự
if (cleanParams['@timkiem'] !== undefined && String(cleanParams['@timkiem']).length < 2) {
  errors.push('Từ khóa tìm kiếm cần ít nhất 2 ký tự ạ!');
}

if (errors.length > 0) {
  return [{ json: { isValid: false, cleanParams: {}, errorMsg: errors[0], validationLevel: 'BUSINESS' } }];
}

return [{ json: { isValid: true, cleanParams, errorMsg: null, validationLevel: 'PASSED' } }];

const err = $input.first().json;
const msg = err.message || err.error || 'Lỗi không xác định';
console.error('[V5 Error]', msg);
return [{ json: { status: 'error', message: 'Dạ, hệ thống đang xử lý chậm, anh/chị thử lại sau vài giây nhé! ', data: [], count: 0, apiCode: 'SYSTEM_ERROR' } }];

const k = $input.first().json || {};
const apiCode = $('LIB ConfidenceDecision').first().json.intent || '';
const origMsg = $('LIB NormalizeInput').first().json.rawMessage || '';
if (apiCode === 'casual_chat' || apiCode === 'null' || !apiCode) {
  return [{ json: { status:'success', message:'', data:[], count:0, apiCode, needsRagFallback:true, originalMessage:origMsg } }];
}
if (k.status === 'error') {
  return [{ json: { status:'error', message: k.reply||k.message||'Có lỗi xảy ra.', data:[], count:0, apiCode, needsRagFallback:false } }];
}
const count = k.count || 0;
if (count === 0 || (k.data||[]).length === 0) {
  return [{ json: { 
    status: 'success', 
    message: 'Dạ, hệ thống hiện không tìm thấy dữ liệu nào phù hợp với yêu cầu trên ạ. Sếp kiểm tra lại giúp em nhé! ', 
    data: [], 
    count: 0, 
    apiCode, 
    needsRagFallback: false 
  } }];
}
return [{ json: { status:'success', message: k.reply||('Tìm thấy '+count+' kết quả.'), data:k.data||[], count, apiCode, needsRagFallback:false } }];

const r = $input.first().json || {};
return [{ json: { 
  status: r.status || 'success', 
  message: r.message || 'Hệ thống AI xử lý chậm, vui lòng thử lại sau.', 
  data: r.data || [], 
  count: r.count || 0, 
  apiCode: r.apiCode || 'AGENT_V6' 
} }];

// NODE: "Save Context"
// Vị trí: Đặt TRƯỚC "Respond Fast", sau Format Chat/RAG Response

const inp = $input.first().json;
const sessionId = $('LIB NormalizeInput').first().json.sessionId || 'default';

// Lấy kết quả từ node trước (Format Chat Response hoặc Format RAG Response)
const responseData = {
  status:   inp.status   || 'success',
  message:  inp.message  || '',
  data:     inp.data     || [],
  count:    inp.count    || 0,
  apiCode:  inp.apiCode  || ''
};

// Lấy thông tin intent để cập nhật context
const parsedIntent = $('LIB ConfidenceDecision').first().json;

// Cập nhật context với entity mới nhất
const newCtx = JSON.stringify({
  lastMaKhachHang: parsedIntent.params?.['@MaKhachHang'] 
                   || $('LIB NormalizeInput').first().json.ctx?.lastMaKhachHang 
                   || '',
  lastMaSanPham:   parsedIntent.params?.['@timkiem'] 
                   || $('LIB NormalizeInput').first().json.ctx?.lastMaSanPham 
                   || '',
  lastIntent:      parsedIntent.apiCode || '',
  updatedAt:       Date.now()
});

// Ghi vào Static Data (không cần Redis, tự động persist)
const staticData = $getWorkflowStaticData('global');
staticData['ctx_' + sessionId] = newCtx;

// Pass through response data để Respond Fast sử dụng
return [{ json: responseData }];
